// Covers: CONF-20. docs/components.md is generated by scripts/gen-catalog.mjs from the catalog and
// the stream fixtures. It must be up to date, every chart example must render, and every example
// config must give the KS answer that the page states.
import { describe, it, expect, vi, beforeAll, beforeEach, afterEach } from 'vitest';
import { createElement, act } from 'react';
import { createRoot, type Root } from 'react-dom/client';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { setKsProvider } from '../../src/core/ks';
import type { ChartCoreProps } from '../../src/core/chart';
import { installRemote, resetFakes, settle } from '../components/cases';
import { kalturaNames, loadCatalog, readJson } from './helpers';

(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
vi.setConfig({ testTimeout: 30000, hookTimeout: 60000 });

type Stream = { component: string; messages: unknown[] };
type ChartExample = { chartType: ChartCoreProps['chartType']; row: Record<string, unknown>; xKey: string; yKeys: string[] };
interface Generator {
  renderComponentsDoc(catalog: unknown, streams: Stream[], chartExamples: ChartExample[]): string;
  configOf(stream: Stream): Record<string, unknown>;
  KS_NOT_REQUIRED: Record<string, string>;
}

const generator = (await import(/* @vite-ignore */ pathToFileURL(resolve(process.cwd(), 'scripts/gen-catalog.mjs')).href)) as Generator;
const catalog = loadCatalog();
const streams = readJson<Stream[]>('test/conformance/fixtures/streams.json');
const examples = readJson<ChartExample[]>('test/conformance/fixtures/chart-examples.json');

// ResizeObserver reports a width, so the responsive charts leave their empty state.
(globalThis as { ResizeObserver?: unknown }).ResizeObserver = class {
  constructor(private cb: (entries: unknown[]) => void) {}
  observe() {
    setTimeout(() => this.cb([{ contentRect: { width: 640, height: 300 } }]), 0);
  }
  disconnect() {}
  unobserve() {}
};

describe('CONF-20: docs/components.md', () => {
  it('CONF-20: is what the generator builds (run "npm run gen:catalog -- --write")', () => {
    expect(readFileSync('docs/components.md', 'utf8')).toBe(generator.renderComponentsDoc(catalog, streams, examples));
  });

  it('CONF-20: has a stream fixture for every Kaltura component', () => {
    expect(streams.map(stream => stream.component)).toEqual(kalturaNames(catalog));
  });

  it('CONF-20: has one chart example for every chartType', () => {
    const part = catalog.components.KalturaChart.allOf[2] as unknown as { properties: { chartType: { enum: string[] } } };
    expect(examples.map(example => example.chartType).sort()).toEqual([...part.properties.chartType.enum].sort());
  });
});

describe('CONF-20: chart examples render', () => {
  let root: Root;
  let host: HTMLElement;
  beforeAll(() => {
    // GeoMap fetches the world map. A failed fetch gives an empty map, which is fine here.
    vi.stubGlobal('fetch', vi.fn(async () => new Response('{}', { status: 500 })));
  });
  beforeEach(() => {
    vi.spyOn(console, 'error').mockImplementation(() => {});
    host = document.body.appendChild(document.createElement('div'));
    root = createRoot(host);
  });
  afterEach(() => {
    act(() => root.unmount());
    document.body.innerHTML = '';
    vi.restoreAllMocks();
  });

  it.each(examples)('CONF-20: $chartType', async ({ chartType, row, xKey, yKeys }) => {
    const { ChartCore } = await import('../../src/core/chart');
    await act(async () => root.render(createElement(ChartCore, { chartType, data: [row, row, row], xKey, yKeys })));
    await act(async () => {
      await new Promise(done => setTimeout(done, 50));
    });
    const drawn = host.querySelector('.kaltura-chart-body')?.querySelectorAll('svg *').length ?? 0;
    // jsdom has no canvas, so the word cloud can only pass the prop check here. The geo map is empty without its map file.
    if (chartType === 'wordcloud') return expect(host.querySelectorAll('.kaltura-load-error').length).toBe(0);
    expect([host.querySelectorAll('[role="alert"]').length, chartType === 'geo' || drawn > 0]).toEqual([0, true]);
  });
});

describe('CONF-20: the KS column', () => {
  beforeAll(async () => {
    installRemote();
    await import('../../src/adapters/webcomponent/index');
  });
  beforeEach(() => {
    resetFakes();
    setKsProvider(undefined);
    vi.spyOn(console, 'error').mockImplementation(() => {});
  });
  afterEach(() => {
    document.body.innerHTML = '';
    vi.restoreAllMocks();
  });

  it.each(kalturaNames(catalog))('CONF-20: %s without a KS', async name => {
    const tag = (catalog['x-kaltura-adapters'] as { webcomponent: { customElements: string[] } }).webcomponent.customElements[kalturaNames(catalog).indexOf(name)];
    const stream = streams.find(entry => entry.component === name) as Stream;
    const el = document.createElement(tag) as HTMLElement & { config: unknown };
    el.config = generator.configOf(stream);
    await act(async () => void document.body.appendChild(el));
    await settle();
    expect(el.textContent?.includes('Invalid ks')).toBe(!(name in generator.KS_NOT_REQUIRED));
  });
});
